def inside(x, y):
    return x > 0 and y > 0 and (x / c_x + y / b_y) < 1

# Backward reconstruction using uniqueness criterion:
# If s = x/C + y/B < 1/d, the last label must be A; else exactly one of B or C applies
# depending on whether y >= B/d or x >= C/d, respectively.
