            # label B
            prevx = d * curx - 0
            prevy = d * cury - b_y
        else:
            # label C
            prevx = d * curx - c_x
            prevy = d * cury - 0
    # Validate interior
    if not inside(prevx, prevy):
        return (False, None)
    curx, cury = prevx, prevy

# Now (curx, cury) should equal P1 with integer coordinates
if curx.denominator != 1 or cury.denominator != 1:
    # The reconstruction did not yield integer coordinates; invalid instance
    return (False, None)
k = curx.numerator
m = cury.numerator
# Final sanity check: P1 is interior
if not (k > 0 and m > 0 and (Fraction(k, c_x) + Fraction(m, b_y)) < 1):
    return (False, None)

